// In-place fused SiLU-multiply: gate[i] = silu(gate[i]) * up[i]
// 4 elements per thread for better ILP
// Vectorized float4 version for better memory throughput when N % 4 == 0
__global__ void fused_silu_mul_inplace_kernel(
    scalar_t* __restrict__ gate,         // [N] - modified in place
    const scalar_t* __restrict__ up,     // [N]
    int N
) {
    int base_idx = (blockIdx.x * blockDim.x + threadIdx.x) * 4;
    if (N % 4 == 0) {
        float4* gate_f4 = (float4*)gate;
        const float4* up_f4 = (const float4*)up;
        int num_float4 = N / 4;
        for (int i = base_idx / 4; i < num_float4; i += blockDim.x * gridDim.x) {
            float4 g = gate_f4[i];
            float4 u = __ldg(&up_f4[i]);
            float4 silu_g;
            silu_g.x = g.x / (1.0f + expf(-g.x));
            silu_g.y = g.y / (1.0f + expf(-g.y));
            silu_g.z = g.z / (1.0f + expf(-g.z));
            silu_g.w = g.w / (1.0f + expf(-g.w));
            gate_f4[i] = make_float4(silu_g.x * u.x, silu_g.y * u.y, silu_g.z * u.z, silu_g.w * u.w);
        }
    } else {
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            int idx = base_idx + i;
            if (idx < N) {
                float g = static_cast<float>(gate[idx]);
                float u = static_cast<float>(up[idx]);
                float silu_g = g / (1.0f + expf(-g));
                gate[idx] = static_cast<scalar_t>(silu_g * u);
            }
        }
    }
}

