__global__ void rotary_embedding_kernel(
    scalar_t* __restrict__ x,          // [batch, seq_len, num_heads, head_dim]
    const int* __restrict__ positions,  // [batch, seq_len]
    int seq_len,
    int num_heads,
    int head_dim,
    float base,
    int total_pairs
) {
    // Each thread handles one (batch, seq, head, pair_idx) element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    // Bounds guard (benchmark change 00's reason, kept): the launcher rounds the grid up to 256-thread blocks, so
    // a decode step's k (4 K/V heads x 32 pairs = 128 pairs) runs stray threads that, unguarded, read and write
    // past the tensors (compute-sanitizer on an H100: the stock kernel's rotary_embedding.cu:34, thread 128).
    if (idx >= total_pairs) return;
    int half_dim = head_dim / 2;

    // Decode flat index → (batch, seq, head, pair)
    int pair_idx = idx % half_dim;
    int tmp = idx / half_dim;
    int head = tmp % num_heads;
